body='#!/usr/bin/env python3\n"""Native TextEncoder/TextDecoder checks in window, dedicated worker and two realms."""\nimport argparse, hashlib, http.server, json, os, subprocess, tempfile, threading\nfrom pathlib import Path\nCORE = "function runTextCodecChecks() {\\n const rows=[];\\n const check=(name,fn)=>{try{rows.push({name,passed:fn()===true});}catch(e){rows.push({name,passed:false,error:e.name+\': \'+e.message});}};\\n const throws=(kind,fn)=>{try{fn();return false;}catch(e){return e.name===kind;}};\\n const eq=(a,b)=>JSON.stringify(a)===JSON.stringify(b);\\n const bytes=a=>new Uint8Array(a);\\n check(\'default decoder attributes\',()=>{const d=new TextDecoder();return d.encoding===\'utf-8\'&&!d.fatal&&!d.ignoreBOM;});\\n for(const [label,name] of [[\' \\\\tUTF-8\\\\r\\\\n\',\'utf-8\'],[\'latin1\',\'windows-1252\'],[\'ASCII\',\'windows-1252\'],[\'Utf-16\',\'utf-16le\'],[\'unicodefffe\',\'utf-16be\'],[\'Shift_JIS\',\'shift_jis\'],[\'iso-8859-8-i\',\'iso-8859-8-i\']])\\n  check(\'canonical label \'+JSON.stringify(label),()=>new TextDecoder(label).encoding===name);\\n for(const label of [\'\',\'utf-7\',\'utf-8\\\\0\',\'\\\\u00a0utf-8\',\'utf8\\\\uFEFF\',\'replacement\',\'iso-2022-cn\',\'hz-gb-2312\'])\\n  check(\'invalid label \'+JSON.stringify(label),()=>throws(\'RangeError\',()=>new TextDecoder(label)));\\n check(\'Symbol labels throw TypeError\',()=>throws(\'TypeError\',()=>new TextDecoder(Symbol(\'utf-8\'))));\\n check(\'constructor options null is empty\',()=>!new TextDecoder(\'utf-8\',null).fatal);\\n check(\'constructor options primitive rejects\',()=>throws(\'TypeError\',()=>new TextDecoder(\'utf-8\',1)));\\n check(\'options convert before label algorithm\',()=>{const marker=new Error(\'marker\');try{new TextDecoder(\'bad\',{get fatal(){throw marker;}});}catch(e){return e===marker;}return false;});\\n check(\'label uses string coercion hint once\',()=>{const seen=[];const label={[Symbol.toPrimitive](hint){seen.push(hint);return \'utf-8\';}};return new TextDecoder(label).encoding===\'utf-8\'&&seen.join(\',\')===\'string\';});\\n check(\'decoder attributes are readonly\',()=>{const d=new TextDecoder(\'utf-8\',{fatal:1,ignoreBOM:1});return d.fatal&&d.ignoreBOM&&!Object.hasOwn(d,\'fatal\')&&!Object.getOwnPropertyDescriptor(TextDecoder.prototype,\'fatal\').set;});\\n check(\'decoder brand cannot be forged\',()=>throws(\'TypeError\',()=>TextDecoder.prototype.decode.call(Object.create(TextDecoder.prototype),bytes([65]))));\\n check(\'encoder brand cannot be forged\',()=>throws(\'TypeError\',()=>TextEncoder.prototype.encode.call(Object.create(TextEncoder.prototype),\'A\')));\\n check(\'encoder Symbol input rejects\',()=>throws(\'TypeError\',()=>new TextEncoder().encode(Symbol(\'x\'))));\\n check(\'encoder defaults and null conversion\',()=>{const e=new TextEncoder();return e.encoding===\'utf-8\'&&e.encode().length===0&&e.encode(undefined).length===0&&eq([...e.encode(null)],[110,117,108,108]);});\\n check(\'encoder replaces lone surrogates\',()=>eq([...new TextEncoder().encode(\'\\\\uD800A\\\\uDC00\')],[239,191,189,65,239,191,189]));\\n check(\'encoder preserves non-BMP scalars\',()=>eq([...new TextEncoder().encode(\'\\\\u{1D306}\')],[240,157,140,134]));\\n check(\'encodeInto never writes partial scalar\',()=>{const out=new Uint8Array(3).fill(170),r=new TextEncoder().encodeInto(\'\\\\u{1D306}A\',out);return r.read===0&&r.written===0&&eq([...out],[170,170,170]);});\\n check(\'encodeInto counts UTF16 units\',()=>{const out=new Uint8Array(4),r=new TextEncoder().encodeInto(\'\\\\u{1D306}A\',out);return r.read===2&&r.written===4&&eq([...out],[240,157,140,134]);});\\n check(\'encodeInto bounds offset writes\',()=>{const out=new Uint8Array(8).fill(170),r=new TextEncoder().encodeInto(\'A¢B\',out.subarray(2,5));return r.read===2&&r.written===3&&eq([...out],[170,170,65,194,162,170,170,170]);});\\n check(\'encodeInto consumes only fitted surrogate replacements\',()=>{const out=new Uint8Array(4),r=new TextEncoder().encodeInto(\'\\\\uD800A\\\\uDC00\',out);return r.read===2&&r.written===4&&eq([...out],[239,191,189,65]);});\\n check(\'encodeInto requires both arguments\',()=>throws(\'TypeError\',()=>new TextEncoder().encodeInto(\'A\')));\\n for(const make of [()=>new Int8Array(4),()=>new Uint8ClampedArray(4),()=>new Uint16Array(2),()=>new DataView(new ArrayBuffer(4)),()=>new ArrayBuffer(4),()=>[]])\\n  check(\'encodeInto rejects destination \'+rows.length,()=>throws(\'TypeError\',()=>new TextEncoder().encodeInto(\'A\',make())));\\n check(\'encodeInto ignores shadowed public length\',()=>{const out=new Uint8Array(2);Object.defineProperty(out,\'length\',{value:0});const r=new TextEncoder().encodeInto(\'A\',out);return r.read===1&&r.written===1&&out[0]===65;});\\n check(\'encodeInto rejects Proxy without traps\',()=>{let calls=0;const p=new Proxy(new Uint8Array(2),{get(){calls++;return 2;}});return throws(\'TypeError\',()=>new TextEncoder().encodeInto(\'A\',p))&&calls===0;});\\n check(\'decode empty and explicit undefined\',()=>new TextDecoder().decode()===\'\'&&new TextDecoder().decode(undefined)===\'\');\\n check(\'decode rejects null\',()=>throws(\'TypeError\',()=>new TextDecoder().decode(null)));\\n check(\'decode rejects fake buffer properties\',()=>throws(\'TypeError\',()=>new TextDecoder().decode({buffer:new ArrayBuffer(1),byteLength:1,byteOffset:0})));\\n check(\'decode accepts a DataView byte range\',()=>new TextDecoder().decode(new DataView(bytes([65,66,67]).buffer,1,1))===\'B\');\\n check(\'decode ignores shadowed view properties\',()=>{const a=bytes([65,66,67]).subarray(1,2);Object.defineProperties(a,{buffer:{value:new ArrayBuffer(0)},byteLength:{value:0},byteOffset:{value:0}});return new TextDecoder().decode(a)===\'B\';});\\n check(\'decode observes mutation by options getter\',()=>{const a=bytes([65]);return new TextDecoder().decode(a,{get stream(){a[0]=66;return false;}})===\'B\';});\\n check(\'decode invalid options rejects\',()=>throws(\'TypeError\',()=>new TextDecoder().decode(bytes([65]),1)));\\n check(\'UTF8 maximal invalid subsequences\',()=>new TextDecoder().decode(bytes([0xE0,0x80,0x80,65,0xF0,0x90,0x80]))===\'\\\\uFFFD\\\\uFFFD\\\\uFFFDA\\\\uFFFD\');\\n check(\'UTF8 fatal rejects malformed sequence\',()=>throws(\'TypeError\',()=>new TextDecoder(\'utf-8\',{fatal:true}).decode(bytes([0xC0,0xAF]))));\\n check(\'UTF8 fatal accepts literal replacement scalar\',()=>new TextDecoder(\'utf-8\',{fatal:true}).decode(bytes([0xEF,0xBF,0xBD]))===\'\\\\uFFFD\');\\n check(\'UTF8 BOM is stripped by default\',()=>new TextDecoder().decode(bytes([0xEF,0xBB,0xBF,65]))===\'A\');\\n check(\'UTF8 ignoreBOM preserves BOM\',()=>new TextDecoder(\'utf-8\',{ignoreBOM:true}).decode(bytes([0xEF,0xBB,0xBF,65]))===\'\\\\uFEFFA\');\\n check(\'independent decodes reset BOM state\',()=>{const d=new TextDecoder(),a=bytes([239,187,191,65]);return d.decode(a)===\'A\'&&d.decode(a)===\'A\';});\\n check(\'UTF8 streaming splits a scalar\',()=>{const d=new TextDecoder();return d.decode(bytes([240,159]),{stream:true})===\'\'&&d.decode(bytes([152]),{stream:true})===\'\'&&d.decode(bytes([128]))===\'😀\';});\\n check(\'UTF8 streaming splits BOM\',()=>{const d=new TextDecoder();return d.decode(bytes([239]),{stream:true})===\'\'&&d.decode(bytes([187]),{stream:true})===\'\'&&d.decode(bytes([191,65]))===\'A\';});\\n check(\'UTF8 streaming reconsumes invalid continuation\',()=>{const d=new TextDecoder();return d.decode(bytes([0xE2]),{stream:true})===\'\'&&d.decode(bytes([65]))===\'\\\\uFFFDA\';});\\n check(\'UTF8 flush emits one unfinished replacement\',()=>{const d=new TextDecoder();return d.decode(bytes([0xF0,0x90,0x80]),{stream:true})===\'\'&&d.decode()===\'\\\\uFFFD\'&&d.decode()===\'\';});\\n check(\'UTF8 fatal flush rejects incomplete scalar\',()=>{const d=new TextDecoder(\'utf-8\',{fatal:true});return d.decode(bytes([0xF0,0x90]),{stream:true})===\'\'&&throws(\'TypeError\',()=>d.decode());});\\n check(\'UTF16LE sample\',()=>new TextDecoder(\'utf-16le\').decode(bytes([65,0,0x3D,0xD8,0,0xDE]))===\'A😀\');\\n check(\'UTF16BE sample\',()=>new TextDecoder(\'utf-16be\').decode(bytes([0,65,0xD8,0x3D,0xDE,0]))===\'A😀\');\\n check(\'UTF16 does not sniff opposite-endian BOM\',()=>new TextDecoder(\'utf-16le\').decode(bytes([0xFE,0xFF,0,65]))===\'\\\\uFFFE\\\\u4100\');\\n check(\'UTF16 streaming spans bytes and surrogate pair\',()=>{const d=new TextDecoder(\'utf-16le\');return d.decode(bytes([0x3D]),{stream:true})===\'\'&&d.decode(bytes([0xD8,0]),{stream:true})===\'\'&&d.decode(bytes([0xDE]))===\'😀\';});\\n check(\'UTF16 high surrogate reconsumes next unit\',()=>new TextDecoder(\'utf-16le\').decode(bytes([0x3D,0xD8,65,0]))===\'\\\\uFFFDA\');\\n check(\'UTF16 high surrogate and odd EOF form one error\',()=>{const d=new TextDecoder(\'utf-16le\');return d.decode(bytes([0x3D,0xD8,65]),{stream:true})===\'\'&&d.decode()===\'\\\\uFFFD\';});\\n check(\'UTF16 fatal rejects unpaired surrogate\',()=>throws(\'TypeError\',()=>new TextDecoder(\'utf-16le\',{fatal:true}).decode(bytes([0,0xDC]))));\\n check(\'UTF16 fatal accepts literal replacement scalar\',()=>new TextDecoder(\'utf-16le\',{fatal:true}).decode(bytes([0xFD,0xFF]))===\'\\\\uFFFD\');\\n check(\'Latin1 aliases use Windows1252 table\',()=>new TextDecoder(\'latin1\').decode(bytes([0x80,0xE9]))===\'€é\');\\n check(\'legacy encodings do not strip UTF8 BOM bytes\',()=>new TextDecoder(\'windows-1252\').decode(bytes([239,187,191]))===\'ï»¿\');\\n check(\'ShiftJIS native table decoding\',()=>new TextDecoder(\'shift_jis\').decode(bytes([0x82,0xA0]))===\'あ\');\\n check(\'ShiftJIS fatal invalid pair\',()=>throws(\'TypeError\',()=>new TextDecoder(\'shift_jis\',{fatal:true}).decode(bytes([0x82,0x20]))));\\n check(\'ISO2022JP native state within one decode\',()=>new TextDecoder(\'iso-2022-jp\').decode(bytes([27,36,66,36,34,27,40,66,65]))===\'あA\');\\n check(\'undefined legacy index is replacement\',()=>new TextDecoder(\'iso-8859-3\').decode(bytes([0xA5]))===\'\\\\uFFFD\');\\n check(\'undefined legacy index fatal error\',()=>throws(\'TypeError\',()=>new TextDecoder(\'iso-8859-3\',{fatal:true}).decode(bytes([0xA5]))));\\n check(\'decode rejects resizable buffer before options getter\',()=>{const b=new ArrayBuffer(2,{maxByteLength:4});let called=0;return throws(\'TypeError\',()=>new TextDecoder().decode(b,{get stream(){called++;return false;}}))&&called===0;});\\n check(\'decode rejects view backed by resizable buffer\',()=>throws(\'TypeError\',()=>new TextDecoder().decode(new Uint8Array(new ArrayBuffer(2,{maxByteLength:4})))));\\n check(\'encodeInto rejects resizable destination\',()=>throws(\'TypeError\',()=>new TextEncoder().encodeInto(\'A\',new Uint8Array(new ArrayBuffer(2,{maxByteLength:4})))));\\n check(\'encodeInto converts source before destination validation\',()=>{let converted=0;const input={toString(){converted++;return \'A\';}};return throws(\'TypeError\',()=>new TextEncoder().encodeInto(input,new Uint8Array(new ArrayBuffer(2,{maxByteLength:4}))))&&converted===1;});\\n check(\'fixed shared buffers remain supported\',()=>{const b=new SharedArrayBuffer(2),a=new Uint8Array(b);const r=new TextEncoder().encodeInto(\'AB\',a);return r.read===2&&r.written===2&&new TextDecoder().decode(b)===\'AB\';});\\n check(\'decode rejects growable shared buffer\',()=>throws(\'TypeError\',()=>new TextDecoder().decode(new SharedArrayBuffer(2,{maxByteLength:4}))));\\n check(\'encodeInto rejects growable shared destination\',()=>throws(\'TypeError\',()=>new TextEncoder().encodeInto(\'A\',new Uint8Array(new SharedArrayBuffer(2,{maxByteLength:4})))));\\n return rows;\\n}\\n"\nHTML = \'<!doctype html><meta charset="utf-8"><title>Text codec window, worker and realm regression</title><iframe></iframe><script>\\n\\\'use strict\\\';\\n__CORE__\\nconst results=[];\\nfunction append(scope,row){const out={i:results.length,scope,name:row.name,ok:row.passed===true,error:row.error||null};results.push(out);console.log(\\\'TEXT_CODEC_CHECK \\\'+JSON.stringify(out));}\\nfor(const row of runTextCodecChecks())append(\\\'window\\\',row);\\nconst w=document.querySelector(\\\'iframe\\\').contentWindow;\\nconst check=(name,fn)=>{try{append(\\\'cross-realm\\\',{name,passed:fn()===true});}catch(e){append(\\\'cross-realm\\\',{name,passed:false,error:e.name+\\\': \\\'+e.message});}};\\ncheck(\\\'parent getter reads child decoder state\\\',()=>Object.getOwnPropertyDescriptor(TextDecoder.prototype,\\\'encoding\\\').get.call(new w.TextDecoder(\\\'latin1\\\'))===\\\'windows-1252\\\');\\ncheck(\\\'child getter reads parent decoder state\\\',()=>Object.getOwnPropertyDescriptor(w.TextDecoder.prototype,\\\'fatal\\\').get.call(new TextDecoder(\\\'utf-8\\\',{fatal:true}))===true);\\ncheck(\\\'parent decode uses child encoding state\\\',()=>TextDecoder.prototype.decode.call(new w.TextDecoder(\\\'utf-16le\\\'),new Uint8Array([65,0]))===\\\'A\\\');\\ncheck(\\\'child decode uses parent encoding state\\\',()=>w.TextDecoder.prototype.decode.call(new TextDecoder(),new w.Uint8Array([0xE2,0x82,0xAC]))===\\\'€\\\');\\ncheck(\\\'parent encode allocates in child receiver realm\\\',()=>{const a=TextEncoder.prototype.encode.call(new w.TextEncoder(),\\\'A\\\');return a instanceof w.Uint8Array&&!(a instanceof Uint8Array)&&a[0]===65;});\\ncheck(\\\'child encode allocates in parent receiver realm\\\',()=>{const a=w.TextEncoder.prototype.encode.call(new TextEncoder(),\\\'A\\\');return a instanceof Uint8Array&&!(a instanceof w.Uint8Array)&&a[0]===65;});\\ncheck(\\\'parent encodeInto writes child destination\\\',()=>{const a=new w.Uint8Array(3),r=TextEncoder.prototype.encodeInto.call(new w.TextEncoder(),\\\'¢A\\\',a);return r.read===2&&r.written===3&&a[0]===194&&a[1]===162&&a[2]===65;});\\ncheck(\\\'public properties cannot change private child decoder\\\',()=>{const d=new w.TextDecoder(\\\'utf-8\\\',{fatal:true});Object.defineProperties(d,{fatal:{value:false},encoding:{value:\\\'windows-1252\\\'}});try{TextDecoder.prototype.decode.call(d,new Uint8Array([255]));}catch(e){return e.name===\\\'TypeError\\\';}return false;});\\nfunction finish(workerIssue){const passed=results.filter(r=>r.ok).length;const result={total:results.length,passed,failed:results.length-passed,workerIssue:workerIssue||null};window.__textCodecResult={result,rows:results};console.log(\\\'TEXT_CODEC_RESULTS \\\'+JSON.stringify(result));document.documentElement.setAttribute(\\\'data-text-codec-done\\\',\\\'1\\\');}\\nlet done=false;\\nconst worker=new Worker(\\\'/worker.js\\\');\\nconst timeout=setTimeout(()=>{if(done)return;done=true;worker.terminate();finish(\\\'worker timeout\\\');},10000);\\nworker.onmessage=e=>{if(done)return;done=true;clearTimeout(timeout);worker.terminate();if(!Array.isArray(e.data)){finish(\\\'invalid worker payload\\\');return;}for(const row of e.data)append(\\\'worker\\\',row);finish(null);};\\nworker.onerror=e=>{if(done)return;done=true;clearTimeout(timeout);worker.terminate();e.preventDefault();finish(String(e.message||\\\'worker error\\\'));};\\n</script>\'.replace("__CORE__", CORE)\nWORKER = "\'use strict\';\\n" + CORE + \'\\npostMessage(runTextCodecChecks());\\n\'\nEXPECTED = 170\n\nclass Handler(http.server.BaseHTTPRequestHandler):\n    def do_GET(self):\n        data = (WORKER if self.path.split(\'?\', 1)[0] == \'/worker.js\' else HTML).encode()\n        self.send_response(200)\n        self.send_header(\'Content-Type\', \'application/javascript; charset=utf-8\' if self.path.startswith(\'/worker.js\') else \'text/html; charset=utf-8\')\n        self.send_header(\'Content-Length\', str(len(data)))\n        self.send_header(\'Cross-Origin-Opener-Policy\', \'same-origin\')\n        self.send_header(\'Cross-Origin-Embedder-Policy\', \'require-corp\')\n        self.end_headers()\n        self.wfile.write(data)\n    def log_message(self, *_):\n        pass\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--binary\', type=Path, required=True)\n    args = parser.parse_args()\n    binary = args.binary.resolve()\n    if not binary.is_file():\n        parser.error(\'binary does not exist\')\n    server = http.server.ThreadingHTTPServer((\'127.0.0.1\', 0), Handler)\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\n    thread.start()\n    try:\n        with tempfile.TemporaryDirectory(prefix=\'lume-text-codec-\') as profile:\n            env = {k: v for k, v in os.environ.items() if not k.startswith(\'LUMEN_\')}\n            env.update(LUMEN_PROFILE_DIR=profile, LUMEN_CONSOLE=\'1\', JSRUN_UNTIL_ATTR=\'data-text-codec-done\')\n            run = subprocess.run([str(binary), \'http://127.0.0.1:%d/\' % server.server_port, \'12000\'],\n                                 capture_output=True, text=True, env=env, timeout=18)\n    except subprocess.TimeoutExpired as exc:\n        print(\'TEXT_CODEC_INFRA \' + json.dumps({\'error\': \'timeout\', \'seconds\': exc.timeout}))\n        return 2\n    finally:\n        server.shutdown()\n        server.server_close()\n        thread.join(timeout=2)\n    print(run.stdout, end=\'\')\n    print(run.stderr, end=\'\')\n    rows, summaries = [], []\n    for line in (run.stdout + \'\\n\' + run.stderr).splitlines():\n        for marker, target in [(\'TEXT_CODEC_CHECK \', rows), (\'TEXT_CODEC_RESULTS \', summaries)]:\n            at = line.find(marker)\n            if at >= 0:\n                try:\n                    target.append(json.loads(line[at + len(marker):]))\n                except json.JSONDecodeError:\n                    print(\'TEXT_CODEC_INFRA malformed JSON\')\n                    return 2\n    if run.returncode != 0 or len(rows) != EXPECTED or len(summaries) != 1:\n        print(\'TEXT_CODEC_INFRA \' + json.dumps({\'exit\': run.returncode, \'checks\': len(rows), \'summaries\': len(summaries)}))\n        return 2\n    if [r.get(\'i\') for r in rows] != list(range(EXPECTED)):\n        print(\'TEXT_CODEC_INFRA duplicate or missing check index\')\n        return 2\n    passed = sum(r.get(\'ok\') is True for r in rows)\n    summary = summaries[0]\n    if (summary.get(\'total\') != EXPECTED or summary.get(\'passed\') != passed or\n            summary.get(\'failed\') != EXPECTED - passed or summary.get(\'workerIssue\') is not None):\n        print(\'TEXT_CODEC_INFRA inconsistent or incomplete summary\')\n        return 2\n    print(\'TEXT_CODEC_RECEIPT \' + json.dumps({\n        \'binary\': str(binary), \'binary_sha256\': hashlib.sha256(binary.read_bytes()).hexdigest(),\n        \'fixture_sha256\': hashlib.sha256(HTML.encode()).hexdigest(),\n        \'worker_sha256\': hashlib.sha256(WORKER.encode()).hexdigest(),\n        \'total\': EXPECTED, \'passed\': passed, \'failed\': EXPECTED - passed,\n        \'scopes\': {scope: {\'total\': sum(r[\'scope\'] == scope for r in rows),\n                           \'passed\': sum(r[\'scope\'] == scope and r[\'ok\'] for r in rows)}\n                   for scope in [\'window\', \'worker\', \'cross-realm\']}}))\n    return 0 if passed == EXPECTED else 1\n\nif __name__ == \'__main__\':\n    raise SystemExit(main())\n'.encode()
expected='5ff54ee9929df32e9922d3af45224ce568fe72345451aefc527c05244a187050'
assert hashlib.sha256(body).hexdigest()==expected
assert not path.exists() or path.read_bytes()==body,'unexpected existing codec fixture'
path.write_bytes(body)
print(json.dumps({'path':str(path.relative_to(root)),'sha256':expected,'checks':170,'scope':'window81+dedicated-worker81+cross-realm8','productionChanged':False}))
